const dynamic = { name: "env", variable: "DYNAMIC" };

export function exercise() {
  const result = {};
  result.initial = Deno.permissions.querySync(dynamic).state;
  result.request = Deno.permissions.requestSync(dynamic).state;
  result.after = Deno.permissions.querySync(dynamic).state;
  result.value = Deno.env.get("DYNAMIC");
  result.revoke = Deno.permissions.revokeSync(dynamic).state;
  result["after-revoke"] = Deno.permissions.querySync(dynamic).state;
  try {
    Deno.env.get("DYNAMIC");
    result["read-after-revoke"] = "allowed";
  } catch (error) {
    result["read-after-revoke"] = error.name;
  }
  result.above =
    Deno.permissions.requestSync({ name: "env", variable: "OUTSIDE" }).state;
  result.never =
    Deno.permissions.requestSync({ name: "env", variable: "NEVER" }).state;
  return result;
}
